import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
shelf_ids = [rec['values']['ShelfID'] for rec in capacity_records]
shelf_caps = {rec['values']['ShelfID']: float(rec['values']['Capacity']) for rec in capacity_records}
product_names = [rec['values']['ProductName'] for rec in product_records]
product_values = {rec['values']['ProductName']: float(rec['values']['Value']) for rec in product_records}
product_weights = {rec['values']['ProductName']: float(rec['values']['Weight']) for rec in product_records}
if len(shelf_ids) != 10:
    raise ValueError('Expected 10 shelves, got %d' % len(shelf_ids))
if len(product_names) != 20:
    raise ValueError('Expected 20 products, got %d' % len(product_names))
if set(product_values) != set(product_names) or set(product_weights) != set(product_names):
    raise ValueError('Product value/weight keys do not match product names')
if set(shelf_caps) != set(shelf_ids):
    raise ValueError('Shelf capacity keys do not match shelf ids')
m = gp.Model('Retail_Display_Allocation')
x_vars = m.addVars(shelf_ids, product_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((product_values[j] * x_vars[i, j] for i in shelf_ids for j in product_names)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((product_weights[j] * x_vars[i, j] for j in product_names)) <= shelf_caps[i] for i in shelf_ids), name='')
first_product = product_names[0]
m.addConstr(gp.quicksum((x_vars[i, first_product] for i in shelf_ids)) >= 5, name='min_smartphone')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
